def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n < 5:
        return 'C'
    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    opp_def = sum(1 for a in opp if a == 'D')
    me_def = sum(1 for a in me if a == 'D')
    last_opp = opp[-1]
    last_me = me[-1]
    recent_opp_def = sum(1 for a in opp[-10:] if a == 'D')
    if opp_def >= n - 1:
        return 'D'
    if n > 85:
        if opp_def * 2 <= n:
            return 'D' if last_opp == 'C' else 'C'
        if opp_def * 3 >= n * 2:
            return 'D'
    if recent_opp_def >= 8:
        return 'D'
    if last_opp == 'D' and last_me == 'C':
        return 'D'
    if last_opp == 'D' and last_me == 'D':
        if n >= 2 and opp[-2] == 'C':
            if rng.random() < 0.7:
                return 'C'
        if rng.random() < 0.3:
            return 'C'
        return 'D'
    if last_opp == 'C':
        if last_me == 'D' and n >= 2 and opp[-2] == 'C':
            return 'C'
        if n >= 20 and opp_def * 10 <= n:
            if rng.random() < 0.05:
                return 'D'
            return 'C'
        if recent_opp_def >= 3:
            return 'D' if rng.random() < 0.4 else 'C'
        return 'C'
    return 'C'
